import logging

from ta_moler.device.nokia_proxy_pc import NokiaProxyPc
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class Asoc(NokiaProxyPc):
    r"""
    Asoc device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      ASOC1:
       DEVICE_CLASS: ta_moler.device.asoc.Asoc
       CONNECTION_HOPS:
         UNIX_LOCAL:
           PROXY_PC:
             execute_command: ssh # default value
             command_params:
               expected_prompt: proxy_pc_prompt
               host: host_ip
               login: login
               password: password
         LINUX:
           PROXY_PC:
             execute_command: exit # default value
             command_params:
               expected_prompt: proxy_pc_prompt
    - without PROXY_PC:
      ENB1:
       DEVICE_CLASS: ta_moler.device.fzm_console.FzmConsole
       CONNECTION_HOPS:
         UNIX_LOCAL:
           LINUX:
             execute_command: telnet # default value
             command_params:
               host: tty_server_host
               port: tty_port
    """

    linux = "LINUX"
    uboot = "UBOOT"
    aashell = "AASHELL"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else Asoc.linux
        super(Asoc, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection, io_type=io_type,
                                   variant=variant, io_constructor_kwargs=io_constructor_kwargs,
                                   initial_state=initial_state, lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.asoc')

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        config = {
            Asoc.connection_hops: {
                Asoc.proxy_pc: {  # from
                    Asoc.linux: {  # to
                        "execute_command": "telnet",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'(root@asc-0a:.*>)|(uboot#)',
                            "login": "toor4nsn",
                            "password": "oZPS0POrRieRtu",
                        },
                        "required_command_params": [
                            "host",
                            "port",
                        ]
                    },
                },
                Asoc.linux: {  # from
                    Asoc.proxy_pc: {  # to
                        "execute_command": "exit_telnet",  # using command
                        "command_params": {  # with parameters
                        },
                        "required_command_params": [
                            "expected_prompt"
                        ]
                    },
                    Asoc.uboot: {  # to
                        "execute_command": "reboot_uboot",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'uboot#',
                        },
                        "required_command_params": [
                        ]
                    },
                    Asoc.aashell: {  # to
                        "execute_command": "telnet",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'AaShell>',
                            "host": "0",
                            "port": 15007,
                            "set_timeout": None,
                        },
                        "required_command_params": [
                        ]
                    },
                },
                Asoc.aashell: {
                    Asoc.linux: {  # to
                        "execute_command": "quit",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'root@asc-0a:.*>',
                        },
                        "required_command_params": [
                        ]
                    },
                },
                Asoc.uboot: {
                    Asoc.linux: {  # to
                        "execute_command": "boot",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'root@asc-0a:.*>',
                        },
                        "required_command_params": [
                        ]
                    },
                }
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        transitions = {
            Asoc.linux: {
                Asoc.proxy_pc: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Asoc.aashell: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Asoc.uboot: {
                    "action": [
                        "_execute_command_to_change_state"
                    ]
                }
            },
            Asoc.proxy_pc: {
                Asoc.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
            },
            Asoc.aashell: {
                Asoc.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            Asoc.uboot: {
                Asoc.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            Asoc.linux:
                self._configurations[Asoc.connection_hops][Asoc.aashell][Asoc.linux][
                    "command_params"]["expected_prompt"],
            Asoc.uboot:
                self._configurations[Asoc.connection_hops][Asoc.linux][Asoc.uboot][
                    "command_params"]["expected_prompt"],
            Asoc.aashell:
                self._configurations[Asoc.connection_hops][Asoc.linux][Asoc.aashell][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        state_prompts = {
            Asoc.linux:
                self._configurations[Asoc.connection_hops][Asoc.aashell][Asoc.linux][
                    "command_params"]["expected_prompt"],
            Asoc.uboot:
                self._configurations[Asoc.connection_hops][Asoc.linux][Asoc.uboot][
                    "command_params"]["expected_prompt"],
            Asoc.aashell:
                self._configurations[Asoc.connection_hops][Asoc.linux][Asoc.aashell][
                    "command_params"]["expected_prompt"],

        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            Asoc.not_connected: {
                Asoc.linux: Asoc.unix_local,
                Asoc.aashell: Asoc.unix_local,
                Asoc.uboot: Asoc.unix_local,
            },
            Asoc.linux: {
                Asoc.not_connected: Asoc.proxy_pc,
                Asoc.unix_local: Asoc.proxy_pc,
                Asoc.unix_local_root: Asoc.proxy_pc
            },
            Asoc.aashell: {
                Asoc.unix_local: Asoc.linux,
                Asoc.proxy_pc: Asoc.linux,
                Asoc.not_connected: Asoc.linux,
                Asoc.uboot: Asoc.linux,
                Asoc.unix_local_root: Asoc.linux
            },
            Asoc.uboot: {
                Asoc.unix_local: Asoc.linux,
                Asoc.proxy_pc: Asoc.linux,
                Asoc.not_connected: Asoc.linux,
                Asoc.aashell: Asoc.linux,
                Asoc.unix_local_root: Asoc.linux
            },
            Asoc.unix_local: {
                Asoc.linux: Asoc.proxy_pc,
                Asoc.aashell: Asoc.proxy_pc,
                Asoc.uboot: Asoc.proxy_pc,
            },
            Asoc.proxy_pc: {
                Asoc.aashell: Asoc.linux,
                Asoc.uboot: Asoc.linux,
            },
            Asoc.unix_local_root: {
                Asoc.proxy_pc: Asoc.unix_local,
                Asoc.not_connected: Asoc.unix_local,
                Asoc.uboot: Asoc.unix_local,
                Asoc.aashell: Asoc.unix_local,
                Asoc.linux: Asoc.unix_local
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(Asoc, self)._get_packages_for_state(state, observer)
        if not available:
            if state == Asoc.linux:
                available = {
                    Asoc.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.shared.enblinux',
                                'ta_moler.cmd.asoc.linux'],
                    Asoc.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.asoc']}
            elif state == Asoc.aashell:
                available = {Asoc.cmds: ['ta_moler.cmd.shared.aashell', 'ta_moler.cmd.asoc.aashell'],
                             Asoc.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.asoc']}
            elif state == Asoc.uboot:
                available = {Asoc.cmds: ['ta_moler.cmd.shared.argon', 'ta_moler.cmd.asoc.uboot'],
                             Asoc.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.asoc']}
            if available:
                return available[observer]

        return available
